4|int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
5|{
6|    if(size < 1) return 0;
7|
8|    /* Avoid timeout with long inputs */
9|    if(size > (64 * 1024)) return 0;
10|
11|    if(data[size-1] != '\0') return 0;
12|
13|    const uint8_t* ptr = data;
14|    utf8proc_int32_t c = 0, c_prev = 0, state = 0;
15|    unsigned int options;
16|    utf8proc_ssize_t ret, bytes = 0;
17|    utf8proc_uint8_t *str = NULL;
18|    size_t len = strlen((const char*)data);
19|
20|    while(bytes != len)
21|    {
22|        ret = utf8proc_iterate(ptr, -1, &c);
23|
24|        if(ret < 0 || ret == 0) break;
25|
26|        bytes += ret;
27|        ptr += ret;
28|
29|        utf8proc_tolower(c);
30|        utf8proc_toupper(c);
31|        utf8proc_totitle(c);
32|        utf8proc_islower(c);
33|        utf8proc_isupper(c);
34|        utf8proc_charwidth(c);
35|        utf8proc_category(c);
36|        utf8proc_category_string(c);
37|        utf8proc_codepoint_valid(c);
38|
39|        utf8proc_grapheme_break(c_prev, c);
40|        utf8proc_grapheme_break_stateful(c_prev, c, &state);
41|
42|        c_prev = c;
43|    }
44|
45|    utf8proc_int32_t *copy = size >= 4 ? malloc(size) : NULL;
46|
47|    if(copy)
48|    {
49|        size /= 4; /* number of utf8proc_int32_t code points that fit in copy */
50|
51|        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS;
52|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
53|        utf8proc_normalize_utf32(copy, size, options);
54|
55|        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2LS;
56|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
57|        utf8proc_normalize_utf32(copy, size, options);
58|
59|        options = UTF8PROC_STRIPCC | UTF8PROC_NLF2PS;
60|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
61|        utf8proc_normalize_utf32(copy, size, options);
62|
63|        options = UTF8PROC_STRIPCC;
64|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
65|        utf8proc_normalize_utf32(copy, size, options);
66|
67|        options = UTF8PROC_LUMP;
68|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
69|        utf8proc_normalize_utf32(copy, size, options);
70|
71|        options = 0;
72|        memcpy(copy, data, size * sizeof(utf8proc_int32_t));
73|        utf8proc_normalize_utf32(copy, size, options);
74|
75|        free(copy);
76|    }
77|
78|    utf8proc_free(utf8proc_NFD(data));
79|    utf8proc_free(utf8proc_NFC(data));
80|    utf8proc_free(utf8proc_NFKD(data));
81|    utf8proc_free(utf8proc_NFKC(data));
82|    utf8proc_free(utf8proc_NFKC_Casefold(data));
83|
84|    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_STRIPNA);
85|    utf8proc_free(str);
86|
87|    utf8proc_map(data, len, &str, UTF8PROC_LUMP | UTF8PROC_NLF2LS | UTF8PROC_NLF2PS);
88|    utf8proc_free(str);
89|
90|    utf8proc_map(data, len, &str, UTF8PROC_COMPOSE | UTF8PROC_STRIPMARK);
91|    utf8proc_free(str);
92|
93|    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_DECOMPOSE);
94|    utf8proc_free(str);
95|
96|    utf8proc_map(data, len, &str, UTF8PROC_CHARBOUND | UTF8PROC_COMPOSE);
97|    utf8proc_free(str);
98|
99|    return 0;
100|}

