66|{
67|    /* baseline: composition still happens */
68|    {
69|        utf8proc_int32_t input[] = {0x0041, 0x0301};        /* "A" + combining acute */
70|        utf8proc_int32_t expected[] = {0x00c1};             /* "\u00c1" */
71|        check_normalize_utf32("compose", input, 2, expected, 1);
72|    }
73|
