75|       (unsafe_get_property would read past utf8proc_stage1table) */
76|    {
77|        utf8proc_int32_t input[] = {0x0041, 0x110000, 0x0301};
78|        check_normalize_utf32("out-of-range codepoint", input, 3, input, 3);
79|    }
