81|    /* likewise the grapheme-break sentinel written by utf8proc_decompose_char */
82|    {
83|        utf8proc_int32_t input[] = {0x0041, -1, 0x0301};
84|        check_normalize_utf32("grapheme-break sentinel", input, 3, input, 3);
85|    }
86|
87|    printf("PASSED: utf8proc_normalize_utf32 preserves uninterpretable codepoints\n");
