367|static utf8proc_int32_t seqindex_decode_index(const utf8proc_uint32_t seqindex)
368|{
369|  const utf8proc_uint16_t *entry = &utf8proc_sequences[seqindex];
370|  return seqindex_decode_entry(&entry);
