445|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_decompose_char(utf8proc_int32_t uc, utf8proc_int32_t *dst, utf8proc_ssize_t bufsize, unsigned int options, utf8proc_int32_t *last_boundclass) {
446|  const utf8proc_property_t *property;
447|  utf8proc_propval_t category;
448|  utf8proc_int32_t hangul_sindex;
449|  if (uc < 0 || uc >= 0x110000) return UTF8PROC_ERROR_NOTASSIGNED;
450|  property = unsafe_get_property(uc);
451|  category = property->category;
452|  hangul_sindex = uc - UTF8PROC_HANGUL_SBASE;
453|  if (options & (UTF8PROC_COMPOSE|UTF8PROC_DECOMPOSE)) {
454|    if (hangul_sindex >= 0 && hangul_sindex < UTF8PROC_HANGUL_SCOUNT) {
455|      utf8proc_int32_t hangul_tindex;
456|      if (bufsize >= 1) {
457|        dst[0] = UTF8PROC_HANGUL_LBASE +
458|          hangul_sindex / UTF8PROC_HANGUL_NCOUNT;
459|        if (bufsize >= 2) dst[1] = UTF8PROC_HANGUL_VBASE +
460|          (hangul_sindex % UTF8PROC_HANGUL_NCOUNT) / UTF8PROC_HANGUL_TCOUNT;
461|      }
462|      hangul_tindex = hangul_sindex % UTF8PROC_HANGUL_TCOUNT;
463|      if (!hangul_tindex) return 2;
464|      if (bufsize >= 3) dst[2] = UTF8PROC_HANGUL_TBASE + hangul_tindex;
465|      return 3;
466|    }
467|  }
468|  if (options & UTF8PROC_REJECTNA) {
469|    if (!category) return UTF8PROC_ERROR_NOTASSIGNED;
470|  }
471|  if (options & UTF8PROC_IGNORE) {
472|    if (property->ignorable) return 0;
473|  }
474|  if (options & UTF8PROC_STRIPNA) {
475|    if (!category) return 0;
476|  }
477|  if (options & UTF8PROC_LUMP) {
478|    if (category == UTF8PROC_CATEGORY_ZS) utf8proc_decompose_lump(0x0020);
479|    if (uc == 0x2018 || uc == 0x2019 || uc == 0x02BC || uc == 0x02C8)
480|      utf8proc_decompose_lump(0x0027);
481|    if (category == UTF8PROC_CATEGORY_PD || uc == 0x2212)
482|      utf8proc_decompose_lump(0x002D);
483|    if (uc == 0x2044 || uc == 0x2215) utf8proc_decompose_lump(0x002F);
484|    if (uc == 0x2236) utf8proc_decompose_lump(0x003A);
485|    if (uc == 0x2039 || uc == 0x2329 || uc == 0x3008)
486|      utf8proc_decompose_lump(0x003C);
487|    if (uc == 0x203A || uc == 0x232A || uc == 0x3009)
488|      utf8proc_decompose_lump(0x003E);
489|    if (uc == 0x2216) utf8proc_decompose_lump(0x005C);
490|    if (uc == 0x02C4 || uc == 0x02C6 || uc == 0x2038 || uc == 0x2303)
491|      utf8proc_decompose_lump(0x005E);
492|    if (category == UTF8PROC_CATEGORY_PC || uc == 0x02CD)
493|      utf8proc_decompose_lump(0x005F);
494|    if (uc == 0x02CB) utf8proc_decompose_lump(0x0060);
495|    if (uc == 0x2223) utf8proc_decompose_lump(0x007C);
496|    if (uc == 0x223C) utf8proc_decompose_lump(0x007E);
497|    if ((options & UTF8PROC_NLF2LS) && (options & UTF8PROC_NLF2PS)) {
498|      if (category == UTF8PROC_CATEGORY_ZL ||
499|          category == UTF8PROC_CATEGORY_ZP)
500|        utf8proc_decompose_lump(0x000A);
501|    }
502|  }
503|  if (options & UTF8PROC_STRIPMARK) {
504|    if (category == UTF8PROC_CATEGORY_MN ||
505|      category == UTF8PROC_CATEGORY_MC ||
506|      category == UTF8PROC_CATEGORY_ME) return 0;
507|  }
508|  if (options & UTF8PROC_CASEFOLD) {
509|    if (property->casefold_seqindex != UINT16_MAX) {
510|      return seqindex_write_char_decomposed(property->casefold_seqindex, dst, bufsize, options, last_boundclass);
511|    }
512|  }
513|  if (options & (UTF8PROC_COMPOSE|UTF8PROC_DECOMPOSE)) {
514|    if (property->decomp_seqindex != UINT16_MAX &&
515|        (!property->decomp_type || (options & UTF8PROC_COMPAT))) {
516|      return seqindex_write_char_decomposed(property->decomp_seqindex, dst, bufsize, options, last_boundclass);
517|    }
518|  }
519|  if (options & UTF8PROC_CHARBOUND) {
520|    utf8proc_bool boundary;
521|    boundary = grapheme_break_extended(0, property->boundclass, 0, property->indic_conjunct_break,
522|                                       last_boundclass);
523|    if (boundary) {
524|      if (bufsize >= 1) dst[0] = -1; /* sentinel value for grapheme break */
525|      if (bufsize >= 2) dst[1] = uc;
526|      return 2;
527|    }
528|  }
529|  if (bufsize >= 1) *dst = uc;
530|  return 1;
531|}
