533|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_decompose(
534|  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen,
535|  utf8proc_int32_t *buffer, utf8proc_ssize_t bufsize, unsigned int options
536|) {
537|    return utf8proc_decompose_custom(str, strlen, buffer, bufsize, options, NULL, NULL);
