617|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_normalize_utf32(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
618|  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored */
619|  if (options & (UTF8PROC_NLF2LS | UTF8PROC_NLF2PS | UTF8PROC_STRIPCC)) {
620|    utf8proc_ssize_t rpos;
621|    utf8proc_ssize_t wpos = 0;
622|    utf8proc_int32_t uc;
623|    for (rpos = 0; rpos < length; rpos++) {
624|      uc = buffer[rpos];
625|      if (uc == 0x000D && rpos < length-1 && buffer[rpos+1] == 0x000A) rpos++;
626|      if (uc == 0x000A || uc == 0x000D || uc == 0x0085 ||
627|          ((options & UTF8PROC_STRIPCC) && (uc == 0x000B || uc == 0x000C))) {
628|        if (options & UTF8PROC_NLF2LS) {
629|          if (options & UTF8PROC_NLF2PS) {
630|            buffer[wpos++] = 0x000A;
631|          } else {
632|            buffer[wpos++] = 0x2028;
633|          }
634|        } else {
635|          if (options & UTF8PROC_NLF2PS) {
636|            buffer[wpos++] = 0x2029;
637|          } else {
638|            buffer[wpos++] = 0x0020;
639|          }
640|        }
641|      } else if ((options & UTF8PROC_STRIPCC) &&
642|          (uc < 0x0020 || (uc >= 0x007F && uc < 0x00A0))) {
643|        if (uc == 0x0009) buffer[wpos++] = 0x0020;
644|      } else {
645|        buffer[wpos++] = uc;
646|      }
647|    }
648|    length = wpos;
649|  }
650|  if (options & UTF8PROC_COMPOSE) {
651|    utf8proc_int32_t *starter = NULL;
652|    const utf8proc_property_t *starter_property = NULL;
653|    utf8proc_propval_t max_combining_class = -1;
654|    utf8proc_ssize_t rpos;
655|    utf8proc_ssize_t wpos = 0;
656|    for (rpos = 0; rpos < length; rpos++) {
657|      utf8proc_int32_t current_char = buffer[rpos];
658|      if (current_char < 0 || current_char >= 0x110000) {
659|        /* grapheme-break sentinel or out-of-range codepoint: pass it through
660|           unchanged, but never compose across it, since we cannot inspect it
661|           (unsafe_get_property would OOB on utf8proc_stage1table, idx = uc >> 8).
662|           utf8proc_reencode drops what cannot be encoded, so this is invisible
663|           to utf8proc_map. */
664|        buffer[wpos++] = current_char;
665|        starter = NULL;
666|        starter_property = NULL;
667|        max_combining_class = -1;
668|        continue;
669|      }
670|      const utf8proc_property_t *current_property = unsafe_get_property(current_char);
671|      if (starter && current_property->combining_class > max_combining_class) {
672|        /* combination perhaps possible */
673|        utf8proc_int32_t hangul_lindex;
674|        utf8proc_int32_t hangul_sindex;
675|        hangul_lindex = *starter - UTF8PROC_HANGUL_LBASE;
676|        if (hangul_lindex >= 0 && hangul_lindex < UTF8PROC_HANGUL_LCOUNT) {
677|          utf8proc_int32_t hangul_vindex;
678|          hangul_vindex = current_char - UTF8PROC_HANGUL_VBASE;
679|          if (hangul_vindex >= 0 && hangul_vindex < UTF8PROC_HANGUL_VCOUNT) {
680|            *starter = UTF8PROC_HANGUL_SBASE +
681|              (hangul_lindex * UTF8PROC_HANGUL_VCOUNT + hangul_vindex) *
682|              UTF8PROC_HANGUL_TCOUNT;
683|            starter_property = NULL;
684|            continue;
685|          }
686|        }
687|        hangul_sindex = *starter - UTF8PROC_HANGUL_SBASE;
688|        if (hangul_sindex >= 0 && hangul_sindex < UTF8PROC_HANGUL_SCOUNT &&
689|            (hangul_sindex % UTF8PROC_HANGUL_TCOUNT) == 0) {
690|          utf8proc_int32_t hangul_tindex;
691|          hangul_tindex = current_char - UTF8PROC_HANGUL_TBASE;
692|          if (hangul_tindex > 0 && hangul_tindex < UTF8PROC_HANGUL_TCOUNT) {
693|            *starter += hangul_tindex;
694|            starter_property = NULL;
695|            continue;
696|          }
697|        }
698|        if (!starter_property) {
699|          /* `*starter` is either a Hangul character, or points into
700|             the table `utf8proc_combinations_combined`. It is always
701|             valid. */
702|          starter_property = unsafe_get_property(*starter);
703|        }
704|        int idx = starter_property->comb_index;
705|        if (idx < 0x3FF && current_property->comb_issecond) {
706|          int len = starter_property->comb_length;
707|          utf8proc_int32_t max_second = utf8proc_combinations_second[idx + len - 1];
708|          if (current_char <= max_second) {
709|            int off;
710|            // TODO: binary search? arithmetic search?
711|            for (off = 0; off < len; ++off) {
712|              utf8proc_int32_t second = utf8proc_combinations_second[idx + off];
713|              if (current_char < second) {
714|                /* not found */
715|                break;
716|              }
717|              if (current_char == second) {
718|                /* found */
719|                utf8proc_int32_t composition = utf8proc_combinations_combined[idx + off];
720|                *starter = composition;
721|                starter_property = NULL;
722|                break;
723|              }
724|            }
725|            if (starter_property == NULL) {
726|              /* found */
727|              continue;
728|            }
729|          }
730|        }
731|      }
732|      buffer[wpos] = current_char;
733|      if (current_property->combining_class) {
734|        if (current_property->combining_class > max_combining_class) {
735|          max_combining_class = current_property->combining_class;
736|        }
737|      } else {
738|        starter = buffer + wpos;
739|        starter_property = NULL;
740|        max_combining_class = -1;
741|      }
742|      wpos++;
743|    }
744|    length = wpos;
745|  }
746|  return length;
747|}
