749|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_reencode(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
750|  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored
751|     ASSERT: 'buffer' has one spare byte of free space at the end! */
752|  length = utf8proc_normalize_utf32(buffer, length, options);
753|  if (length < 0) return length;
754|  {
755|    utf8proc_ssize_t rpos, wpos = 0;
756|    utf8proc_int32_t uc;
757|    if (options & UTF8PROC_CHARBOUND) {
758|        for (rpos = 0; rpos < length; rpos++) {
759|            uc = buffer[rpos];
760|            wpos += charbound_encode_char(uc, ((utf8proc_uint8_t *)buffer) + wpos);
761|        }
762|    } else {
763|        for (rpos = 0; rpos < length; rpos++) {
764|            uc = buffer[rpos];
765|            wpos += utf8proc_encode_char(uc, ((utf8proc_uint8_t *)buffer) + wpos);
766|        }
767|    }
768|    ((utf8proc_uint8_t *)buffer)[wpos] = 0;
769|    return wpos;
770|  }
