779|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_map_custom(
780|  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen, utf8proc_uint8_t **dstptr, unsigned int options,
781|  utf8proc_custom_func custom_func, void *custom_data
782|) {
783|  utf8proc_int32_t *buffer;
784|  utf8proc_ssize_t result;
785|  utf8proc_ssize_t bufsize;
786|  *dstptr = NULL;
787|  bufsize = utf8proc_decompose_custom(str, strlen, NULL, 0, options, custom_func, custom_data);
788|  if (bufsize < 0) return bufsize;
789|  buffer = (utf8proc_int32_t *) malloc(((utf8proc_size_t)bufsize) * sizeof(utf8proc_int32_t) + 1);
790|  if (!buffer) return UTF8PROC_ERROR_NOMEM;
791|  result = utf8proc_decompose_custom(str, strlen, buffer, bufsize, options, custom_func, custom_data);
792|  if (result < 0) {
793|    free(buffer);
794|    return result;
795|  }
796|  /* a custom_func that returns different results across the two decompose
797|     passes can make the second pass longer than the buffer we sized from the
798|     first; reencode would then read and write past the allocation, so bail
799|     out instead of corrupting the heap */
800|  if (result > bufsize) {
801|    free(buffer);
802|    return UTF8PROC_ERROR_OVERFLOW;
803|  }
804|  result = utf8proc_reencode(buffer, result, options);
805|  if (result < 0) {
806|    free(buffer);
807|    return result;
808|  }
809|  {
810|    utf8proc_int32_t *newptr;
811|    newptr = (utf8proc_int32_t *) realloc(buffer, (size_t)result+1);
812|    if (newptr) buffer = newptr;
813|  }
814|  *dstptr = (utf8proc_uint8_t *)buffer;
815|  return result;
816|}
