356|static utf8proc_int32_t seqindex_decode_entry(const utf8proc_uint16_t **entry)
357|{
358|  utf8proc_int32_t entry_cp = **entry;
359|  if ((entry_cp & 0xF800) == 0xD800) {
360|    *entry = *entry + 1;
361|    entry_cp = ((entry_cp & 0x03FF) << 10) | (**entry & 0x03FF);
362|    entry_cp += 0x10000;
363|  }
364|  return entry_cp;
365|}
