373|static utf8proc_ssize_t seqindex_write_char_decomposed(utf8proc_uint16_t seqindex, utf8proc_int32_t *dst, utf8proc_ssize_t bufsize, unsigned int options, utf8proc_int32_t *last_boundclass) {
374|  utf8proc_ssize_t written = 0;
375|  const utf8proc_uint16_t *entry = &utf8proc_sequences[seqindex & 0x3FFF];
376|  int len = seqindex >> 14;
377|  if (len >= 3) {
378|    len = *entry;
379|    entry++;
380|  }
381|  for (; len >= 0; entry++, len--) {
382|    utf8proc_int32_t entry_cp = seqindex_decode_entry(&entry);
383|
384|    utf8proc_ssize_t decomp_result = utf8proc_decompose_char(entry_cp, dst ? dst+written : dst,
385|      (bufsize > written) ? (bufsize - written) : 0, options, last_boundclass);
386|    if (decomp_result < 0) return decomp_result;
387|    written += decomp_result;
388|  }
389|  return written;
