540|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_decompose_custom(
541|  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen,
542|  utf8proc_int32_t *buffer, utf8proc_ssize_t bufsize, unsigned int options,
543|  utf8proc_custom_func custom_func, void *custom_data
544|) {
545|  /* strlen will be ignored, if UTF8PROC_NULLTERM is set in options */
546|  utf8proc_ssize_t wpos = 0;
547|  if ((options & UTF8PROC_COMPOSE) && (options & UTF8PROC_DECOMPOSE))
548|    return UTF8PROC_ERROR_INVALIDOPTS;
549|  if ((options & UTF8PROC_STRIPMARK) &&
550|      !(options & UTF8PROC_COMPOSE) && !(options & UTF8PROC_DECOMPOSE))
551|    return UTF8PROC_ERROR_INVALIDOPTS;
552|  {
553|    utf8proc_int32_t uc;
554|    utf8proc_ssize_t rpos = 0;
555|    utf8proc_ssize_t decomp_result;
556|    utf8proc_int32_t boundclass = UTF8PROC_BOUNDCLASS_START;
557|    while (1) {
558|      if (options & UTF8PROC_NULLTERM) {
559|        utf8proc_ssize_t nread = utf8proc_iterate(str + rpos, -1, &uc);
560|        /* checking of return value is not necessary,
561|           as 'uc' is < 0 in case of error */
562|        if (uc < 0) return UTF8PROC_ERROR_INVALIDUTF8;
563|        if (nread > (utf8proc_ssize_t)SSIZE_MAX - rpos) return UTF8PROC_ERROR_OVERFLOW;
564|        rpos += nread;
565|        if (uc == 0) break;
566|      } else {
567|        if (rpos >= strlen) break;
568|        rpos += utf8proc_iterate(str + rpos, strlen - rpos, &uc);
569|        if (uc < 0) return UTF8PROC_ERROR_INVALIDUTF8;
570|      }
571|      if (custom_func != NULL) {
572|        uc = custom_func(uc, custom_data);   /* user-specified custom mapping */
573|      }
574|      decomp_result = utf8proc_decompose_char(
575|        uc, buffer ? buffer+wpos : buffer, (bufsize > wpos) ? (bufsize - wpos) : 0, options,
576|        &boundclass
577|      );
578|      if (decomp_result < 0) return decomp_result;
579|      /* prohibiting integer overflows due to too long strings: */
580|      if (decomp_result > (utf8proc_ssize_t)(SSIZE_MAX/sizeof(utf8proc_int32_t)/2) - wpos)
581|        return UTF8PROC_ERROR_OVERFLOW;
582|      wpos += decomp_result;
583|    }
584|  }
585|  if ((options & (UTF8PROC_COMPOSE|UTF8PROC_DECOMPOSE)) && bufsize >= wpos) {
586|    utf8proc_ssize_t pos = 0;
587|    while (pos < wpos-1) {
588|      utf8proc_int32_t uc1, uc2;
589|      const utf8proc_property_t *property1, *property2;
590|      uc1 = buffer[pos];
591|      if (uc1 < 0) {
592|        /* skip grapheme break */
593|        pos++;
594|        continue;
595|      }
596|      uc2 = buffer[pos+1];
597|      if (uc2 < 0) {
598|        /* cannot recombine; skip grapheme break */
599|        pos+=2;
600|        continue;
601|      }
602|      property1 = unsafe_get_property(uc1);
603|      property2 = unsafe_get_property(uc2);
604|      if (property1->combining_class > property2->combining_class &&
605|          property2->combining_class > 0) {
606|        buffer[pos] = uc2;
607|        buffer[pos+1] = uc1;
608|        if (pos > 0) pos--; else pos++;
609|      } else {
610|        pos++;
611|      }
612|    }
613|  }
614|  return wpos;
615|}
