784|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_map_custom(
785|  const utf8proc_uint8_t *str, utf8proc_ssize_t strlen, utf8proc_uint8_t **dstptr, unsigned int options,
786|  utf8proc_custom_func custom_func, void *custom_data
787|) {
788|  utf8proc_int32_t *buffer;
789|  utf8proc_ssize_t result;
790|  utf8proc_ssize_t bufsize;
791|  *dstptr = NULL;
792|  bufsize = utf8proc_decompose_custom(str, strlen, NULL, 0, options, custom_func, custom_data);
793|  if (bufsize < 0) return bufsize;
794|  buffer = (utf8proc_int32_t *) malloc(((utf8proc_size_t)bufsize) * sizeof(utf8proc_int32_t) + 1);
795|  if (!buffer) return UTF8PROC_ERROR_NOMEM;
796|  result = utf8proc_decompose_custom(str, strlen, buffer, bufsize, options, custom_func, custom_data);
797|  if (result < 0) {
798|    free(buffer);
799|    return result;
800|  }
801|  /* a custom_func that returns different results across the two decompose
802|     passes can make the second pass longer than the buffer we sized from the
803|     first; reencode would then read and write past the allocation, so bail
804|     out instead of corrupting the heap */
805|  if (result > bufsize) {
806|    free(buffer);
807|    return UTF8PROC_ERROR_OVERFLOW;
808|  }
809|  result = utf8proc_reencode(buffer, result, options);
810|  if (result < 0) {
811|    free(buffer);
812|    return result;
813|  }
814|  {
815|    utf8proc_int32_t *newptr;
816|    newptr = (utf8proc_int32_t *) realloc(buffer, (size_t)result+1);
817|    if (newptr) buffer = newptr;
818|  }
819|  *dstptr = (utf8proc_uint8_t *)buffer;
820|  return result;
