509|    if (property->casefold_seqindex != UINT16_MAX) {
510|      return seqindex_write_char_decomposed(property->casefold_seqindex, dst, bufsize, options, last_boundclass);
511|    }
512|  }
513|  if (options & (UTF8PROC_COMPOSE|UTF8PROC_DECOMPOSE)) {
514|    if (property->decomp_seqindex != UINT16_MAX &&
515|        (!property->decomp_type || (options & UTF8PROC_COMPAT))) {
516|      return seqindex_write_char_decomposed(property->decomp_seqindex, dst, bufsize, options, last_boundclass);
