754|UTF8PROC_DLLEXPORT utf8proc_ssize_t utf8proc_reencode(utf8proc_int32_t *buffer, utf8proc_ssize_t length, unsigned int options) {
755|  /* UTF8PROC_NULLTERM option will be ignored, 'length' is never ignored
756|     ASSERT: 'buffer' has one spare byte of free space at the end! */
757|  length = utf8proc_normalize_utf32(buffer, length, options);
758|  if (length < 0) return length;
759|  {
760|    utf8proc_ssize_t rpos, wpos = 0;
761|    utf8proc_int32_t uc;
762|    if (options & UTF8PROC_CHARBOUND) {
763|        for (rpos = 0; rpos < length; rpos++) {
764|            uc = buffer[rpos];
765|            wpos += charbound_encode_char(uc, ((utf8proc_uint8_t *)buffer) + wpos);
766|        }
767|    } else {
768|        for (rpos = 0; rpos < length; rpos++) {
769|            uc = buffer[rpos];
770|            wpos += utf8proc_encode_char(uc, ((utf8proc_uint8_t *)buffer) + wpos);
771|        }
772|    }
773|    ((utf8proc_uint8_t *)buffer)[wpos] = 0;
774|    return wpos;
775|  }
