4|void checkline(const char *_buf, bool verbose) {
5|    size_t bi = 0, si = 0;
6|    utf8proc_uint8_t src[1024]; /* more than long enough for all of our tests */
7|    const unsigned char *buf = (const unsigned char *) _buf;
8|
9|    while (buf[bi]) {
10|        bi = skipspaces(buf, bi);
11|        if (buf[bi] == 0xc3 && buf[bi+1] == 0xb7) { /* U+00f7 = grapheme break */
12|            src[si++] = '/';
13|            bi += 2;
14|        }
15|        else if (buf[bi] == 0xc3 && buf[bi+1] == 0x97) { /* U+00d7 = no break */
16|            bi += 2;
17|        }
18|        else if (buf[bi] == '#') { /* start of comments */
19|            break;
20|        }
21|        else if (buf[bi] == '/') { /* for convenience, also accept / as grapheme break */
22|            src[si++] = '/';
23|            bi += 1;
24|        }
25|        else { /* hex-encoded codepoint */
26|            size_t dest_len;
27|            size_t len = encode((unsigned char*) (src + si), &dest_len, buf + bi) - 1;
28|            si += dest_len; /* advance to NUL termination */
29|            bi += len;
30|        }
31|    }
32|    if (si && src[si-1] == '/')
33|        --si; /* no break after final grapheme */
34|    src[si] = 0; /* NUL-terminate */
35|
36|    if (si) { /* test utf8proc_map */
37|        utf8proc_uint8_t utf8[1024]; /* copy src without 0xff grapheme separators */
38|        size_t i = 0, j = 0;
39|        utf8proc_ssize_t glen, k;
40|        utf8proc_uint8_t *g; /* utf8proc_map grapheme results */
41|        while (i < si) {
42|            if (src[i] != '/')
43|                utf8[j++] = src[i++];
44|            else
45|                i++;
46|        }
47|        glen = utf8proc_map(utf8, (utf8proc_ssize_t)j, &g, UTF8PROC_CHARBOUND);
48|        if (glen == UTF8PROC_ERROR_INVALIDUTF8) {
49|            /* the test file contains surrogate codepoints, which are only for UTF-16 */
50|            printf("line %zd: ignoring invalid UTF-8 codepoints\n", lineno);
51|        }
52|        else {
53|            check(glen >= 0, "utf8proc_map error = %s",
54|                utf8proc_errmsg(glen));
55|            for (k = 0; k <= glen; ++k)
56|                if (g[k] == 0xff)
57|                    g[k] = '/'; /* easier-to-read output (/ is not in test strings) */
58|            check(!strcmp((char*)g, (char*)src),
59|                "grapheme mismatch: \"%s\" instead of \"%s\"", (char*)g, (char*)src);
60|        }
61|        utf8proc_free(g);
62|    }
63|
64|    if (si) { /* test manual calls to utf8proc_grapheme_break_stateful */
65|        utf8proc_int32_t state = 0, prev_codepoint = 0;
66|        size_t i = 0;
67|        utf8proc_bool expectbreak = false;
68|        do {
69|            utf8proc_int32_t codepoint;
70|            i += (size_t)utf8proc_iterate(src + i, (utf8proc_ssize_t)(si - i), &codepoint);
71|            check(codepoint >= 0, "invalid UTF-8 data");
72|            if (codepoint == 0x002F)
73|                expectbreak = true;
74|            else {
75|                if (prev_codepoint != 0) {
76|                    check(expectbreak == utf8proc_grapheme_break_stateful(prev_codepoint, codepoint, &state),
77|                          "grapheme mismatch: between 0x%04x and 0x%04x in \"%s\"", prev_codepoint, codepoint, (char*) src);
78|                }
79|                expectbreak = false;
80|                prev_codepoint = codepoint;
81|            }
82|        } while (i < si);
83|    }
84|
85|    if (verbose)
86|        printf("passed grapheme test: \"%s\"\n", (char*) src);
87|}

