40|        utf8proc_uint8_t *g; /* utf8proc_map grapheme results */
41|        while (i < si) {
42|            if (src[i] != '/')
43|                utf8[j++] = src[i++];
44|            else
45|                i++;
46|        }
47|        glen = utf8proc_map(utf8, (utf8proc_ssize_t)j, &g, UTF8PROC_CHARBOUND);
48|        if (glen == UTF8PROC_ERROR_INVALIDUTF8) {
49|            /* the test file contains surrogate codepoints, which are only for UTF-16 */
50|            printf("line %zd: ignoring invalid UTF-8 codepoints\n", lineno);
51|        }
52|        else {
53|            check(glen >= 0, "utf8proc_map error = %s",
54|                utf8proc_errmsg(glen));
55|            for (k = 0; k <= glen; ++k)
56|                if (g[k] == 0xff)
57|                    g[k] = '/'; /* easier-to-read output (/ is not in test strings) */
58|            check(!strcmp((char*)g, (char*)src),
59|                "grapheme mismatch: \"%s\" instead of \"%s\"", (char*)g, (char*)src);
60|        }
61|        utf8proc_free(g);
62|    }
