65|        utf8proc_int32_t state = 0, prev_codepoint = 0;
66|        size_t i = 0;
67|        utf8proc_bool expectbreak = false;
68|        do {
69|            utf8proc_int32_t codepoint;
70|            i += (size_t)utf8proc_iterate(src + i, (utf8proc_ssize_t)(si - i), &codepoint);
71|            check(codepoint >= 0, "invalid UTF-8 data");
72|            if (codepoint == 0x002F)
73|                expectbreak = true;
74|            else {
75|                if (prev_codepoint != 0) {
76|                    check(expectbreak == utf8proc_grapheme_break_stateful(prev_codepoint, codepoint, &state),
77|                          "grapheme mismatch: between 0x%04x and 0x%04x in \"%s\"", prev_codepoint, codepoint, (char*) src);
78|                }
79|                expectbreak = false;
80|                prev_codepoint = codepoint;
81|            }
82|        } while (i < si);
83|    }
84|
85|    if (verbose)
86|        printf("passed grapheme test: \"%s\"\n", (char*) src);
